-- Copia del esquema public de producción (Obra Flow) al 31/10/2026 (incluye 072 y 073), solo lo necesario para probar RLS:
-- tipos, tablas (columnas, PK/UNIQUE), funciones usadas por las políticas, RLS y políticas.
-- Se regenera con scripts/db/snapshot_rls.sql (consultas de solo lectura).
\set ON_ERROR_STOP 1

create type public.pricing_rule_type as enum ('FIXED_MANUAL','DIRECT_IMPORT','INDEX_MULTIPLIER','COMPOSITE_INDEX','LABOR_FORMULA');
create type public.snapshot_source_type as enum ('MANUAL','IMPORT','INDEX_CALCULATION','LABOR_CALCULATION','COMPOSITE_CALCULATION','FALLBACK_BASE_COST');
create type public.index_frequency as enum ('MONTHLY','QUARTERLY','ANNUAL','IRREGULAR');

create table public.audit_log (id uuid not null default gen_random_uuid(), actor_id uuid, operation text not null, entity text not null, entity_id text not null, before_data jsonb, after_data jsonb, created_at timestamp with time zone not null default now(), PRIMARY KEY (id));
create table public.budget_items (id uuid not null default gen_random_uuid(), project_id uuid not null, organization_id uuid not null, task_id uuid not null, quantity numeric(14,4) not null default 0, start_date date, end_date date, status text, progress numeric(8,4) not null default 0, dependencies jsonb not null default '[]'::jsonb, manual_duration integer, crews_assigned integer not null default 1, efficiency_factor numeric(8,4), allowance_percent numeric(8,4), created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), sort_order integer, computation_item_id uuid, PRIMARY KEY (id));
create table public.budget_template_items (id uuid not null default gen_random_uuid(), budget_template_id uuid not null, master_task_id uuid not null, quantity numeric(14,4) not null default 1, sort_order integer not null default 0, PRIMARY KEY (id));
create table public.budget_templates (id uuid not null default gen_random_uuid(), organization_id uuid not null, name text not null, description text, category text, is_active boolean not null default true, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), PRIMARY KEY (id));
create table public.budget_versions (id uuid not null default gen_random_uuid(), organization_id uuid not null, project_id uuid not null, version_number integer not null, label text not null, method jsonb not null default '{}'::jsonb, base_period date, target_period date, factors jsonb not null default '{}'::jsonb, totals jsonb not null default '{}'::jsonb, items jsonb not null default '[]'::jsonb, created_at timestamp with time zone not null default now(), created_by uuid default auth.uid(), PRIMARY KEY (id), UNIQUE (project_id, version_number));
create table public.catalog_task_yields (id uuid not null default gen_random_uuid(), master_task_id uuid not null, resource_id uuid not null, quantity numeric(14,6) not null default 1, created_at timestamp with time zone not null default now(), commercial_unit text, conversion_factor numeric(14,6), PRIMARY KEY (id), UNIQUE (master_task_id, resource_id));
create table public.catalogs (id uuid not null default gen_random_uuid(), name text not null, type text not null default 'global'::text, organization_id uuid, is_active boolean not null default true, created_at timestamp with time zone not null default now(), PRIMARY KEY (id));
create table public.computation_items (id uuid not null default gen_random_uuid(), computation_id uuid not null, organization_id uuid not null, chandias_task_id text not null, master_task_id uuid, description text, dims jsonb not null default '{}'::jsonb, quantity numeric(14,4) not null, unidad text not null, materiales_snapshot jsonb not null default '[]'::jsonb, manual_materials jsonb not null default '[]'::jsonb, steel_diameter_mm numeric(6,2), sort_order integer, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), PRIMARY KEY (id));
create table public.cost_index_values (id uuid not null default gen_random_uuid(), index_id uuid not null, period_year smallint not null, period_month smallint not null, value numeric(18,6) not null, variation_pct numeric(8,4), published_at date, source_reference text, metadata jsonb not null default '{}'::jsonb, created_at timestamp with time zone not null default now(), UNIQUE (index_id, period_year, period_month), PRIMARY KEY (id));
create table public.cost_indices (id uuid not null default gen_random_uuid(), tenant_id uuid, code text not null, name text not null, category text, provider text, frequency index_frequency not null default 'MONTHLY'::index_frequency, description text, is_active boolean not null default true, metadata jsonb not null default '{}'::jsonb, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), PRIMARY KEY (id));
create table public.crews (id text not null, organization_id text not null, name text not null, description text, composition jsonb not null default '[]'::jsonb, created_at timestamp with time zone not null default now(), PRIMARY KEY (id));
create table public.invitations (id uuid not null default gen_random_uuid(), organization_id uuid not null, invited_email text, role text not null default 'editor'::text, token text not null default (gen_random_uuid())::text, created_by uuid not null, created_at timestamp with time zone not null default now(), expires_at timestamp with time zone not null default (now() + '7 days'::interval), accepted_at timestamp with time zone, accepted_by uuid, PRIMARY KEY (id), UNIQUE (token));
create table public.labor_categories (id text not null, organization_id text not null, role text not null, basic_hourly_rate numeric not null default 0, social_charges_percent numeric not null default 0, insurance_percent numeric not null default 0, description text, family text, created_at timestamp with time zone not null default now(), code text, PRIMARY KEY (id));
create table public.master_materials (id uuid not null default gen_random_uuid(), organization_id text, code text, name text not null, description text, unit text not null, unit_price numeric(12,4) not null default 0, currency text not null default 'ARS'::text, category text, supplier text, commercial_format text, waste_percent numeric(5,2) default 0, is_active boolean not null default true, last_price_update timestamp with time zone default now(), created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), commercial_unit text, conversion_factor numeric, global_source_id uuid, imported_at timestamp with time zone, last_synced_at timestamp with time zone, local_override boolean not null default false, global_source_updated_at_at_import timestamp with time zone, global_resource_id uuid, technical_yield numeric, technical_yield_unit text, technical_notes text, PRIMARY KEY (id));
create table public.master_task_equipment (id uuid not null default gen_random_uuid(), master_task_id uuid not null, tool_id text not null, tool_name text not null, hours_per_unit numeric(14,4) not null default 0, resource_id uuid, snapshot_cost_per_hour numeric(18,4), PRIMARY KEY (id));
create table public.master_task_labor (id uuid not null default gen_random_uuid(), master_task_id uuid not null, labor_category_id text not null, labor_category_name text not null, quantity numeric(14,4) not null default 1, resource_id uuid, snapshot_hourly_rate numeric(18,4), PRIMARY KEY (id));
create table public.master_task_materials (id uuid not null default gen_random_uuid(), master_task_id uuid not null, master_material_id uuid, material_name text not null, unit text not null, quantity numeric(14,4) not null default 0, waste_percent numeric(8,4) not null default 0, last_known_unit_price numeric(14,4) not null default 0, resource_id uuid, sub_master_task_id uuid, conversion_factor numeric(10,6), commercial_unit text, PRIMARY KEY (id));
create table public.master_tasks (id uuid not null default gen_random_uuid(), organization_id uuid, code text, name text not null, description text, unit text not null, category text, daily_yield numeric(14,4) not null default 1, fixed_cost numeric(14,4) not null default 0, fixed_cost_description text, specifications text, is_active boolean not null default true, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), tags jsonb not null default '[]'::jsonb, source_metadata jsonb, technical_sheet jsonb, PRIMARY KEY (id));
create table public.materials (id text not null, organization_id text not null, name text not null, unit text not null default ''::text, cost numeric not null default 0, category text, min_stock numeric, provider text, family text, description text, commercial_format text, waste_percent numeric, created_at timestamp with time zone not null default now(), code text, commercial_unit text, conversion_factor numeric, PRIMARY KEY (id));
create table public.organization_members (id uuid not null default gen_random_uuid(), organization_id uuid not null, user_id uuid not null, role text not null, created_at timestamp with time zone not null default now(), UNIQUE (organization_id, user_id), PRIMARY KEY (id));
create table public.organization_subscriptions (id uuid not null default gen_random_uuid(), organization_id uuid not null, plan_id text not null default 'starter'::text, status text not null default 'trialing'::text, trial_ends_at timestamp with time zone, current_period_start timestamp with time zone, current_period_end timestamp with time zone, cancel_at_period_end boolean not null default false, canceled_at timestamp with time zone, stripe_customer_id text, stripe_subscription_id text, stripe_price_id text, billing_email text, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), UNIQUE (organization_id), PRIMARY KEY (id), UNIQUE (stripe_customer_id), UNIQUE (stripe_subscription_id));
create table public.organizations (id uuid not null default gen_random_uuid(), name text not null, slug text, created_at timestamp with time zone not null default now(), PRIMARY KEY (id), UNIQUE (slug));
create table public.plan_entitlements (id uuid not null default gen_random_uuid(), plan_id text not null, feature_key text not null, feature_type text not null, bool_value boolean, numeric_value integer, PRIMARY KEY (id), UNIQUE (plan_id, feature_key));
create table public.price_index_sync_runs (id uuid not null default gen_random_uuid(), ran_at timestamp with time zone not null default now(), ok boolean not null, trigger text not null, message text, details jsonb not null default '{}'::jsonb, PRIMARY KEY (id));
create table public.price_indices (id uuid not null default gen_random_uuid(), code text not null, period date not null, value numeric(14,4) not null, source text, created_at timestamp with time zone not null default now(), created_by uuid default auth.uid(), UNIQUE (code, period), PRIMARY KEY (id));
create table public.profiles (id uuid not null, full_name text, default_organization_id uuid, created_at timestamp with time zone not null default now(), email text, system_role text not null default 'user'::text, PRIMARY KEY (id));
create table public.project_computations (id uuid not null default gen_random_uuid(), project_id uuid not null, organization_id uuid not null, name text, status text not null default 'draft'::text, computed_by uuid, computed_at timestamp with time zone not null default now(), created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), PRIMARY KEY (id));
create table public.projects (id uuid not null default gen_random_uuid(), organization_id uuid not null, name text not null, client text, client_id text, currency text not null default 'ARS'::text, start_date date not null, end_date date, status text not null default 'planning'::text, working_days jsonb not null default '[1, 2, 3, 4, 5]'::jsonb, non_working_dates jsonb not null default '[]'::jsonb, workday_hours numeric(8,2) not null default 9, pricing_config jsonb not null default '{}'::jsonb, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), address text, ggd_pct numeric(8,6), ggi_pct numeric(8,6), profit_pct numeric(8,6), tax_pct numeric(8,6), company_name text, surface numeric(14,4), construction_system text, structure_type text, foundation_type text, cost_base date, workday_start_time text, workday_end_time text, lunch_break_duration integer, labor_force jsonb, assigned_crews jsonb, pricing jsonb, dependencies jsonb not null default '[]'::jsonb, cover_image text, PRIMARY KEY (id));
create table public.resource_cost_snapshots (id uuid not null default gen_random_uuid(), tenant_id uuid not null, resource_id uuid not null, effective_date date not null, cost numeric(18,4) not null, currency character(3) not null default 'ARS'::bpchar, source_type snapshot_source_type not null, source_reference text, pricing_rule_id uuid, index_id uuid, index_base_value numeric(18,6), index_current_value numeric(18,6), adjustment_factor numeric(12,6), metadata jsonb not null default '{}'::jsonb, created_at timestamp with time zone not null default now(), PRIMARY KEY (id), UNIQUE (tenant_id, resource_id, effective_date, source_type));
create table public.resource_pricing_rules (id uuid not null default gen_random_uuid(), tenant_id uuid not null, resource_id uuid not null, rule_name text not null, rule_type pricing_rule_type not null, index_id uuid, base_date date, base_cost numeric(18,4), formula_config jsonb not null default '{}'::jsonb, is_active boolean not null default true, priority smallint not null default 0, notes text, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), PRIMARY KEY (id));
create table public.resources (id uuid not null default gen_random_uuid(), catalog_id uuid not null, organization_id uuid, code text not null, name text not null, unit text not null, base_cost numeric(14,4) not null default 0, type text not null, category_name text, social_charges_pct numeric(8,4), is_active boolean not null default true, created_at timestamp with time zone not null default now(), current_snapshot_id uuid, pricing_notes text, commercial_unit text, conversion_factor numeric(14,6), UNIQUE (catalog_id, code), PRIMARY KEY (id));
create table public.stripe_webhook_events (id text not null, type text not null, payload jsonb not null, processed_at timestamp with time zone not null default now(), error text, PRIMARY KEY (id));
create table public.subscription_plans (id text not null, name text not null, stripe_price_id_monthly text, stripe_price_id_yearly text, sort_order integer not null default 0, is_active boolean not null default true, created_at timestamp with time zone not null default now(), PRIMARY KEY (id));
create table public.task_crew_yields (task_id text not null, crew_id text not null, quantity numeric not null default 0, PRIMARY KEY (task_id, crew_id));
create table public.task_labor_yields (id uuid not null default gen_random_uuid(), task_id uuid not null, organization_id uuid not null, labor_category_id text not null, quantity numeric(14,4) not null default 1, PRIMARY KEY (id), UNIQUE (task_id, labor_category_id));
create table public.task_tool_yields (id uuid not null default gen_random_uuid(), task_id uuid not null, organization_id uuid not null, tool_id text not null, hours_per_unit numeric(14,4) not null default 0, PRIMARY KEY (id), UNIQUE (task_id, tool_id));
create table public.task_yields (id uuid not null default gen_random_uuid(), task_id uuid not null, organization_id uuid not null, material_id text not null, quantity numeric(14,4) not null default 0, waste_percent numeric(8,4) not null default 0, PRIMARY KEY (id), UNIQUE (task_id, material_id));
create table public.tasks (id uuid not null default gen_random_uuid(), organization_id uuid not null, master_task_id uuid, code text, name text not null, unit text not null, category text, labor_cost numeric(14,4) not null default 0, daily_yield numeric(14,4) not null default 1, fixed_cost numeric(14,4) not null default 0, fixed_cost_description text, specifications text, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), PRIMARY KEY (id));
create table public.tools (id text not null, organization_id text not null, name text not null, category text not null default ''::text, cost_per_hour numeric not null default 0, family text, created_at timestamp with time zone not null default now(), code text, PRIMARY KEY (id));
create table public.v_org_uuid (organization_id uuid);

-- Funciones usadas por las políticas (definición de producción)
create or replace function public.get_my_organization_ids() returns table(org_id uuid) language sql stable security definer set search_path to 'public' as
$$ select organization_id from public.organization_members where user_id = auth.uid(); $$;
create or replace function public.is_master_admin() returns boolean language sql stable security definer set search_path to 'public' as
$$ select exists (select 1 from public.profiles where id = auth.uid() and system_role = 'master_admin'); $$;
create or replace function public.is_member_of_org(p_org_id uuid) returns boolean language sql security definer set search_path to 'public' as
$$ select exists (select 1 from public.organization_members om where om.user_id = auth.uid() and om.organization_id = p_org_id); $$;
create or replace function public.is_org_admin(p_org_id uuid) returns boolean language sql stable security definer set search_path to 'public' as
$$ select exists (select 1 from public.organization_members where organization_id = p_org_id and user_id = auth.uid() and role in ('owner', 'admin')); $$;
create or replace function public.is_org_member(org_id text) returns boolean language sql stable security definer set search_path to 'public' as
$$ select exists (select 1 from public.organization_members where user_id = auth.uid() and organization_id::text = org_id); $$;
create or replace function public.is_org_member(org_uuid uuid) returns boolean language sql stable security definer set search_path to 'public' as
$$ select exists (select 1 from public.organization_members where user_id = auth.uid() and organization_id = org_uuid); $$;
create or replace function public.is_org_member_with_role(org_id text, min_roles text[]) returns boolean language sql stable security definer set search_path to 'public' as
$$ select exists (select 1 from public.organization_members where user_id = auth.uid() and organization_id::text = org_id and role = any(min_roles)); $$;
create or replace function public.is_org_member_with_role(org_uuid uuid, min_roles text[]) returns boolean language sql stable security definer set search_path to 'public' as
$$ select exists (select 1 from public.organization_members where user_id = auth.uid() and organization_id = org_uuid and role = any(min_roles)); $$;

-- RLS activa en las 40 tablas
do $$ declare r record; begin
  for r in select tablename from pg_tables where schemaname = 'public' loop
    execute format('alter table public.%I enable row level security', r.tablename);
  end loop;
end $$;

grant usage on schema public to anon, authenticated, service_role;
grant all on all tables in schema public to anon, authenticated, service_role;
grant execute on all functions in schema public to anon, authenticated, service_role;

-- Políticas (165) tal como están en producción
create policy audit_log_insert_own on public.audit_log as PERMISSIVE for INSERT to authenticated with check ((actor_id = auth.uid()));
create policy audit_log_select_master_admin on public.audit_log as PERMISSIVE for SELECT to authenticated using (is_master_admin());
create policy budget_items_select on public.budget_items as PERMISSIVE for SELECT to public using ((project_id IN ( SELECT p.id FROM (projects p JOIN organization_members om ON ((om.organization_id = p.organization_id))) WHERE (om.user_id = auth.uid()))));
create policy budget_items_select_member on public.budget_items as PERMISSIVE for SELECT to public using (is_org_member(organization_id));
create policy budget_template_items_select_member on public.budget_template_items as PERMISSIVE for SELECT to public using ((EXISTS ( SELECT 1 FROM budget_templates bt WHERE ((bt.id = budget_template_items.budget_template_id) AND is_org_member(bt.organization_id)))));
create policy budget_templates_select_member on public.budget_templates as PERMISSIVE for SELECT to public using (is_org_member(organization_id));
create policy budget_versions_delete on public.budget_versions as PERMISSIVE for DELETE to authenticated using (is_org_member_with_role(organization_id, ARRAY['owner'::text, 'admin'::text]));
create policy budget_versions_insert on public.budget_versions as PERMISSIVE for INSERT to authenticated with check (is_org_member_with_role(organization_id, ARRAY['owner'::text, 'admin'::text, 'editor'::text]));
create policy budget_versions_select on public.budget_versions as PERMISSIVE for SELECT to authenticated using (is_org_member(organization_id));
create policy citems_delete on public.computation_items as PERMISSIVE for DELETE to authenticated using (is_org_member_with_role(organization_id, ARRAY['owner'::text, 'admin'::text, 'editor'::text]));
create policy citems_insert on public.computation_items as PERMISSIVE for INSERT to authenticated with check (is_org_member_with_role(organization_id, ARRAY['owner'::text, 'admin'::text, 'editor'::text]));
create policy citems_select on public.computation_items as PERMISSIVE for SELECT to authenticated using (is_org_member(organization_id));
create policy citems_update on public.computation_items as PERMISSIVE for UPDATE to authenticated using (is_org_member_with_role(organization_id, ARRAY['owner'::text, 'admin'::text, 'editor'::text])) with check (is_org_member_with_role(organization_id, ARRAY['owner'::text, 'admin'::text, 'editor'::text]));
create policy cost_index_values_delete on public.cost_index_values as PERMISSIVE for DELETE to authenticated using ((EXISTS ( SELECT 1 FROM cost_indices ci WHERE ((ci.id = cost_index_values.index_id) AND (ci.tenant_id IS NOT NULL) AND is_org_member_with_role(ci.tenant_id, ARRAY['owner'::text, 'admin'::text])))));
create policy cost_index_values_insert on public.cost_index_values as PERMISSIVE for INSERT to authenticated with check ((EXISTS ( SELECT 1 FROM cost_indices ci WHERE ((ci.id = cost_index_values.index_id) AND (ci.tenant_id IS NOT NULL) AND is_org_member_with_role(ci.tenant_id, ARRAY['owner'::text, 'admin'::text, 'editor'::text])))));
create policy cost_index_values_select on public.cost_index_values as PERMISSIVE for SELECT to authenticated using ((EXISTS ( SELECT 1 FROM cost_indices ci WHERE ((ci.id = cost_index_values.index_id) AND ((ci.tenant_id IS NULL) OR is_org_member(ci.tenant_id))))));
create policy cost_index_values_update on public.cost_index_values as PERMISSIVE for UPDATE to authenticated using ((EXISTS ( SELECT 1 FROM cost_indices ci WHERE ((ci.id = cost_index_values.index_id) AND (ci.tenant_id IS NOT NULL) AND is_org_member_with_role(ci.tenant_id, ARRAY['owner'::text, 'admin'::text]))))) with check ((EXISTS ( SELECT 1 FROM cost_indices ci WHERE ((ci.id = cost_index_values.index_id) AND (ci.tenant_id IS NOT NULL) AND is_org_member_with_role(ci.tenant_id, ARRAY['owner'::text, 'admin'::text])))));
create policy cost_indices_delete on public.cost_indices as PERMISSIVE for DELETE to authenticated using (((tenant_id IS NOT NULL) AND is_org_member_with_role(tenant_id, ARRAY['owner'::text, 'admin'::text])));
create policy cost_indices_insert on public.cost_indices as PERMISSIVE for INSERT to authenticated with check (((tenant_id IS NOT NULL) AND is_org_member_with_role(tenant_id, ARRAY['owner'::text, 'admin'::text, 'editor'::text])));
create policy cost_indices_select_global on public.cost_indices as PERMISSIVE for SELECT to authenticated using ((tenant_id IS NULL));
create policy cost_indices_select_private on public.cost_indices as PERMISSIVE for SELECT to authenticated using (((tenant_id IS NOT NULL) AND is_org_member(tenant_id)));
create policy cost_indices_update on public.cost_indices as PERMISSIVE for UPDATE to authenticated using (((tenant_id IS NOT NULL) AND is_org_member_with_role(tenant_id, ARRAY['owner'::text, 'admin'::text]))) with check (((tenant_id IS NOT NULL) AND is_org_member_with_role(tenant_id, ARRAY['owner'::text, 'admin'::text])));
create policy crews_delete on public.crews as PERMISSIVE for DELETE to authenticated using ((EXISTS ( SELECT 1 FROM organization_members WHERE ((organization_members.user_id = auth.uid()) AND ((organization_members.organization_id)::text = crews.organization_id) AND (organization_members.role = ANY (ARRAY['owner'::text, 'admin'::text, 'editor'::text]))))));
create policy crews_insert on public.crews as PERMISSIVE for INSERT to authenticated with check ((EXISTS ( SELECT 1 FROM organization_members WHERE ((organization_members.user_id = auth.uid()) AND ((organization_members.organization_id)::text = crews.organization_id) AND (organization_members.role = ANY (ARRAY['owner'::text, 'admin'::text, 'editor'::text]))))));
create policy crews_select on public.crews as PERMISSIVE for SELECT to authenticated using ((EXISTS ( SELECT 1 FROM organization_members WHERE ((organization_members.user_id = auth.uid()) AND ((organization_members.organization_id)::text = crews.organization_id)))));
create policy crews_update on public.crews as PERMISSIVE for UPDATE to authenticated using ((EXISTS ( SELECT 1 FROM organization_members WHERE ((organization_members.user_id = auth.uid()) AND ((organization_members.organization_id)::text = crews.organization_id) AND (organization_members.role = ANY (ARRAY['owner'::text, 'admin'::text, 'editor'::text])))))) with check ((EXISTS ( SELECT 1 FROM organization_members WHERE ((organization_members.user_id = auth.uid()) AND ((organization_members.organization_id)::text = crews.organization_id) AND (organization_members.role = ANY (ARRAY['owner'::text, 'admin'::text, 'editor'::text]))))));
create policy invitations_delete on public.invitations as PERMISSIVE for DELETE to authenticated using (is_org_admin(organization_id));
create policy invitations_insert on public.invitations as PERMISSIVE for INSERT to authenticated with check (is_org_admin(organization_id));
create policy invitations_select on public.invitations as PERMISSIVE for SELECT to authenticated using ((EXISTS ( SELECT 1 FROM organization_members om WHERE ((om.organization_id = invitations.organization_id) AND (om.user_id = auth.uid())))));
create policy labor_categories_delete on public.labor_categories as PERMISSIVE for DELETE to authenticated using ((EXISTS ( SELECT 1 FROM organization_members WHERE ((organization_members.user_id = auth.uid()) AND ((organization_members.organization_id)::text = labor_categories.organization_id) AND (organization_members.role = ANY (ARRAY['owner'::text, 'admin'::text, 'editor'::text]))))));
create policy labor_categories_insert on public.labor_categories as PERMISSIVE for INSERT to authenticated with check ((EXISTS ( SELECT 1 FROM organization_members WHERE ((organization_members.user_id = auth.uid()) AND ((organization_members.organization_id)::text = labor_categories.organization_id) AND (organization_members.role = ANY (ARRAY['owner'::text, 'admin'::text, 'editor'::text]))))));
create policy labor_categories_select on public.labor_categories as PERMISSIVE for SELECT to authenticated using ((EXISTS ( SELECT 1 FROM organization_members WHERE ((organization_members.user_id = auth.uid()) AND ((organization_members.organization_id)::text = labor_categories.organization_id)))));
create policy labor_categories_update on public.labor_categories as PERMISSIVE for UPDATE to authenticated using ((EXISTS ( SELECT 1 FROM organization_members WHERE ((organization_members.user_id = auth.uid()) AND ((organization_members.organization_id)::text = labor_categories.organization_id) AND (organization_members.role = ANY (ARRAY['owner'::text, 'admin'::text, 'editor'::text])))))) with check ((EXISTS ( SELECT 1 FROM organization_members WHERE ((organization_members.user_id = auth.uid()) AND ((organization_members.organization_id)::text = labor_categories.organization_id) AND (organization_members.role = ANY (ARRAY['owner'::text, 'admin'::text, 'editor'::text]))))));
create policy master_materials_delete on public.master_materials as PERMISSIVE for DELETE to authenticated using ((EXISTS ( SELECT 1 FROM organization_members WHERE ((organization_members.user_id = auth.uid()) AND ((organization_members.organization_id)::text = master_materials.organization_id) AND (organization_members.role = ANY (ARRAY['owner'::text, 'admin'::text, 'editor'::text]))))));
